import React, { useState, useEffect } from 'react'
import { MapContainer, TileLayer, Marker, Popup, useMapEvents } from 'react-leaflet'
import { supabase } from './supabaseClient'
import SiteForm from './SiteForm'
import AIReimager from './AIReimager'
import 'leaflet/dist/leaflet.css'
import L from 'leaflet'

// Fix marker icons
delete L.Icon.Default.prototype._getIconUrl
L.Icon.Default.mergeOptions({
  iconRetinaUrl: require('leaflet/dist/images/marker-icon-2x.png'),
  iconUrl: require('leaflet/dist/images/marker-icon.png'),
  shadowUrl: require('leaflet/dist/images/marker-shadow.png'),
})

function AddMarkerOnClick({ onMapClick }) {
  useMapEvents({
    click(e) {
      onMapClick(e.latlng)
    },
  })
  return null
}

function Map() {
  const [sites, setSites] = useState([])
  const [userLocation, setUserLocation] = useState([51.9, -8.47])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)
  const [selectedPosition, setSelectedPosition] = useState(null)
  const [showAIModal, setShowAIModal] = useState(false)
  const [selectedSite, setSelectedSite] = useState(null)

  useEffect(() => {
    loadSites()
    
    if (navigator.geolocation) {
      navigator.geolocation.getCurrentPosition((position) => {
        setUserLocation([position.coords.latitude, position.coords.longitude])
      })
    }
  }, [])

  const loadSites = async () => {
    try {
      const { data, error } = await supabase
        .from('derelict_sites')
        .select('*')
        .order('created_at', { ascending: false })

      if (error) throw error
      setSites(data || [])
    } catch (error) {
      console.error('Error loading sites:', error)
    } finally {
      setLoading(false)
    }
  }

  const handleMapClick = (latlng) => {
    setSelectedPosition(latlng)
    setShowForm(true)
  }

  const handleSiteAdded = (newSite) => {
    setSites([newSite, ...sites])
  }

  if (loading) {
    return <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh' }}>
      Loading map...
    </div>
  }

  return (
    <div style={{ height: '100vh', width: '100%' }}>
      <div style={{
        position: 'absolute',
        top: '10px',
        left: '50%',
        transform: 'translateX(-50%)',
        zIndex: 1000,
        background: 'white',
        padding: '10px 20px',
        borderRadius: '8px',
        boxShadow: '0 2px 10px rgba(0,0,0,0.2)',
        fontFamily: 'Arial, sans-serif'
      }}>
        🏚️ <strong>{sites.length}</strong> derelict sites found | Click map to add new site
      </div>

      <MapContainer
        center={userLocation}
        zoom={13}
        style={{ height: '100%', width: '100%' }}
      >
        <TileLayer
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
          attribution='&copy; OpenStreetMap contributors'
        />
        
        <AddMarkerOnClick onMapClick={handleMapClick} />
        
        {sites.map((site) => (
          <Marker key={site.id} position={[site.latitude, site.longitude]}>
            <Popup maxWidth={300}>
              <div>
                <strong style={{ fontSize: '16px' }}>{site.name}</strong>
                {site.photo_url && (
                  <img 
                    src={site.photo_url} 
                    alt={site.name}
                    style={{ 
                      width: '100%', 
                      height: '150px', 
                      objectFit: 'cover', 
                      marginTop: '10px',
                      borderRadius: '6px'
                    }}
                  />
                )}
                {site.description && (
                  <p style={{ marginTop: '10px', fontSize: '14px' }}>
                    {site.description}
                  </p>
                )}
                <small style={{ color: '#666', display: 'block', marginTop: '5px' }}>
                  {new Date(site.created_at).toLocaleDateString()}
                </small>
                <button
                  onClick={() => {
                    setSelectedSite(site)
                    setShowAIModal(true)
                  }}
                  style={{
                    marginTop: '10px',
                    width: '100%',
                    padding: '8px',
                    backgroundColor: '#9C27B0',
                    color: 'white',
                    border: 'none',
                    borderRadius: '6px',
                    fontSize: '14px',
                    fontWeight: 'bold',
                    cursor: 'pointer'
                  }}
                >
                  ✨ Reimagine with AI
                </button>
              </div>
            </Popup>
          </Marker>
        ))}
      </MapContainer>

      {showForm && selectedPosition && (
        <SiteForm
          position={selectedPosition}
          onClose={() => setShowForm(false)}
          onSiteAdded={handleSiteAdded}
        />
      )}

      {showAIModal && selectedSite && (
        <AIReimager
          site={selectedSite}
          onClose={() => setShowAIModal(false)}
        />
      )}
    </div>
  )
}

export default Map
